package com.chuckerteam.chucker.internal.grpc.format

import com.google.gson.JsonArray
import com.google.gson.JsonElement
import com.google.gson.JsonNull
import com.google.gson.JsonObject
import com.google.gson.JsonPrimitive
import okio.ByteString
import okio.ByteString.Companion.toByteString
import java.lang.reflect.Field
import java.lang.reflect.Modifier
import java.util.concurrent.ConcurrentHashMap

/**
 * Reads messages generated by Square's Wire and converts them to their proto3 JSON representation.
 *
 * Wire annotates every generated field with `@WireField`, which carries the field number, label,
 * proto and JSON names, the adapter and whether the field is redacted. Fields that the client
 * doesn't know are decoded from `unknownFields` and shown as `#<field number>`.
 *
 * Only reflection is used, so Chucker doesn't depend on Wire at all.
 */
internal object WireMessageReader {
    private const val WIRE_MESSAGE = "com.squareup.wire.Message"
    private const val WIRE_FIELD = "com.squareup.wire.WireField"
    private const val WIRE_ENUM = "com.squareup.wire.WireEnum"
    private const val ANY_MESSAGE = "com.squareup.wire.AnyMessage"
    private const val INSTANT = "java.time.Instant"
    private const val DURATION = "java.time.Duration"
    private const val MAX_DEPTH = 64
    private val UNSIGNED_ADAPTERS = listOf("#UINT32", "#FIXED32", "#UINT64", "#FIXED64")

    private val classInfos = ConcurrentHashMap<Class<*>, List<FieldInfo>>()

    fun isMessage(value: Any): Boolean = Reflection.isSubtypeOf(value.javaClass, WIRE_MESSAGE)

    /** Returns the JSON representation of [message], or null when it isn't a Wire message. */
    fun read(message: Any): JsonElement? {
        if (!isMessage(message)) return null
        return readMessage(message, depth = 0)
    }

    private fun readMessage(
        message: Any,
        depth: Int,
    ): JsonElement {
        if (depth > MAX_DEPTH) return JsonPrimitive(message.toString())
        val fields = classInfos.getOrPut(message.javaClass) { fieldsOf(message.javaClass) }
        val json = JsonObject()
        for (field in fields) {
            field.read(message, depth)?.let { json.add(field.jsonName, it) }
        }
        val unknownFields =
            (runCatching { Reflection.call(message, "unknownFields") }.getOrNull() as? ByteString)?.toByteArray()
        if (unknownFields != null && unknownFields.isNotEmpty()) {
            RawProtoDecoder.decode(unknownFields)?.entrySet()?.forEach { (key, value) -> json.add(key, value) }
        }
        return json
    }

    private fun convert(
        value: Any?,
        adapter: String,
        depth: Int,
    ): JsonElement =
        when {
            value == null -> JsonNull.INSTANCE
            value is String -> JsonPrimitive(value)
            value is Boolean -> JsonPrimitive(value)
            value is Number -> convertNumber(value, adapter)
            value is List<*> -> JsonArray().apply { value.forEach { add(convert(it, adapter, depth)) } }
            value is Map<*, *> ->
                JsonObject().apply {
                    value.forEach { (key, item) -> add(key.toString(), convert(item, adapter, depth)) }
                }
            isMessage(value) -> readMessage(value, depth + 1)
            else -> convertOther(value)
        }

    // Unsigned types are mapped to signed Kotlin types, only the adapter tells them apart.
    private fun convertNumber(
        value: Number,
        adapter: String,
    ): JsonElement =
        when {
            value is Long && adapter.isUnsigned() -> ProtoJson.unsigned(value)
            value is Int && adapter.isUnsigned() -> ProtoJson.unsigned(value)
            else -> ProtoJson.number(value)
        }

    private fun convertOther(value: Any): JsonElement =
        when (value) {
            is ByteString -> JsonPrimitive(value.base64())
            is Enum<*> -> JsonPrimitive(value.name)
            // google.protobuf.Empty
            is Unit -> JsonObject()
            else -> convertPlatformType(value)
        }

    // Wire maps some well-known types to platform types instead of generating messages.
    private fun convertPlatformType(value: Any): JsonElement =
        when (value.javaClass.name) {
            INSTANT -> JsonPrimitive(value.toString())
            DURATION ->
                JsonPrimitive(
                    ProtoJson.duration(
                        Reflection.call(value, "getSeconds") as Long,
                        Reflection.call(value, "getNano") as Int,
                    ),
                )
            ANY_MESSAGE -> {
                val bytes = (Reflection.call(value, "getValue") as ByteString).toByteArray()
                JsonObject().apply {
                    addProperty("@type", Reflection.call(value, "getTypeUrl") as String)
                    add("value", RawProtoDecoder.decode(bytes) ?: JsonPrimitive(bytes.toByteString().base64()))
                }
            }
            else -> JsonPrimitive(value.toString())
        }

    private fun String.isUnsigned(): Boolean = UNSIGNED_ADAPTERS.any { endsWith(it) }

    private class FieldInfo(
        val tag: Int,
        val jsonName: String,
        private val field: Field,
        private val label: String,
        private val adapter: String,
        private val isRedacted: Boolean,
    ) {
        fun read(
            message: Any,
            depth: Int,
        ): JsonElement? {
            val value = field.get(message) ?: return null
            val isEmptyCollection = (value is List<*> && value.isEmpty()) || (value is Map<*, *> && value.isEmpty())
            if (isEmptyCollection || (label == "OMIT_IDENTITY" && isIdentity(value))) return null
            return if (isRedacted) JsonPrimitive(ProtoJson.REDACTED) else convert(value, adapter, depth)
        }

        private fun isIdentity(value: Any?): Boolean =
            when (value) {
                null -> true
                is String -> value.isEmpty()
                is Boolean -> !value
                is Float -> value == 0f
                is Double -> value == 0.0
                is Number -> value.toLong() == 0L
                is ByteString -> value.size == 0
                is List<*> -> value.isEmpty()
                is Map<*, *> -> value.isEmpty()
                else -> Reflection.isSubtypeOf(value.javaClass, WIRE_ENUM) && Reflection.call(value, "getValue") == 0
            }
    }

    private fun fieldsOf(clazz: Class<*>): List<FieldInfo> =
        clazz.declaredFields
            .filterNot { Modifier.isStatic(it.modifiers) }
            .mapNotNull { field ->
                val annotation = field.annotations.firstOrNull { it.annotationClass.java.name == WIRE_FIELD }
                annotation?.let { fieldInfo(field, it) }
            }.sortedBy { it.tag }

    private fun fieldInfo(
        field: Field,
        annotation: Annotation,
    ): FieldInfo {
        fun attribute(name: String): Any? =
            runCatching {
                annotation.annotationClass.java
                    .getMethod(name)
                    .invoke(annotation)
            }.getOrNull()

        val declaredName = (attribute("declaredName") as? String).orEmpty().ifEmpty { field.name }
        val jsonName = (attribute("jsonName") as? String).orEmpty().ifEmpty { ProtoJson.jsonName(declaredName) }
        field.isAccessible = true
        return FieldInfo(
            tag = attribute("tag") as Int,
            jsonName = jsonName,
            field = field,
            label = (attribute("label") as? Enum<*>)?.name.orEmpty(),
            adapter = (attribute("adapter") as? String).orEmpty(),
            isRedacted = attribute("redacted") == true,
        )
    }
}
